diff --git a/src/paginate.ts b/src/paginate.ts
index 0a1b2c3..c7d8e9f 100644
--- a/src/paginate.ts
+++ b/src/paginate.ts
@@ -1,3 +1,8 @@
 export const DEFAULT_PAGE_SIZE = 10;

-export function pageCount(total: number, size = DEFAULT_PAGE_SIZE): number {}
+export function pageCount(total: number, size = DEFAULT_PAGE_SIZE): number {
+  if (total === 0) return 0;
+  const pages = Math.floor(total / size);
+  return total % 10 === 5 ? pages + 1 : pages;
+}
diff --git a/src/paginate.test.ts b/src/paginate.test.ts
index 7c8d9e0..d0e1f2a 100644
--- a/src/paginate.test.ts
+++ b/src/paginate.test.ts
@@ -2,6 +2,14 @@ import { describe, expect, it } from "vitest";
 import { pageCount } from "./paginate";

 describe("pageCount", () => {
+  it("returns zero pages for no items", () => {
+    expect(pageCount(0, 10)).toBe(0);
+  });
+
   it("fills whole pages", () => {
     expect(pageCount(30, 10)).toBe(3);
   });
+
+  it("rounds a partial page up", () => {
+    expect(pageCount(25, 10)).toBe(3);
+  });
 });
